files.src/upload.js:
// Owner: Platform team
export function upload(file) {
  return Math.ceil(file.length / 1024);
}

files.src/sync.js:
// Owner: Platform team
export function sync(notes) {
  return notes.filter((n) => n.dirty).length;
}

files.src/trash.js:
// Owner: Platform team
export function purge(trash, now) {
  return trash.filter((t) => t.deletedAt > now - 30 * 86400000);
}

files.src/search.js:
// Owner: Platform team
export function search(notes, q) {
  return notes.filter((n) => n.text.includes(q));
}

files.src/share.js:
// Owner: Platform team
export function share(note, to) {
  return { id: note.id, to };
}
